//! Differential test: line-polygon `intersects` and `crosses` against GEOS (via shapely) on
//! 500 random polygon and line pairs. Some lines run through the polygon's vertices, so the
//! boundary-contact cases are exercised. The reference values are in
//! `tests/fixtures/geos_line_polygon.csv`, generated by `generate_line_polygon_pairs.py`.

#![cfg(feature = "alloc")]

use std::path::PathBuf;

use tpt_gis_geom::line_string::LineString;
use tpt_gis_geom::predicates::line_intersects_polygon;
use tpt_gis_geom::relate::{line_crosses_polygon, line_within_polygon};
use tpt_gis_geom::{Point, Polygon};

fn parse_points(text: &str) -> Vec<Point> {
    text.split_whitespace()
        .map(|pair| {
            let (x, y) = pair.split_once(',').unwrap();
            Point::new(x.parse().unwrap(), y.parse().unwrap())
        })
        .collect()
}

#[test]
fn line_polygon_intersects_and_crosses_agree_with_geos() {
    let path =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/geos_line_polygon.csv");
    let text = std::fs::read_to_string(path).unwrap();
    let mut checked = 0;
    let mut mismatches = Vec::new();
    for (index, row) in text.lines().enumerate() {
        if row.starts_with('#') || row.trim().is_empty() {
            continue;
        }
        let f: Vec<&str> = row.split(';').collect();
        let exterior = parse_points(f[0]);
        let line_points = parse_points(f[1]);
        let want_intersects = f[2] == "1";
        let want_crosses = f[3] == "1";
        let want_within = f[4] == "1";
        let poly = Polygon::new(&exterior, &[]);
        let line = LineString::new(&line_points);
        let got_intersects = line_intersects_polygon(&line, &poly);
        let got_crosses = line_crosses_polygon(&line, &poly);
        let got_within = line_within_polygon(&line, &poly);
        if got_intersects != want_intersects {
            mismatches.push(format!(
                "row {}: intersects ours {got_intersects}, GEOS {want_intersects}",
                index + 1
            ));
        }
        if got_crosses != want_crosses {
            mismatches.push(format!(
                "row {}: crosses ours {got_crosses}, GEOS {want_crosses}",
                index + 1
            ));
        }
        if got_within != want_within {
            mismatches
                .push(format!("row {}: within ours {got_within}, GEOS {want_within}", index + 1));
        }
        checked += 1;
    }
    assert!(checked >= 500, "only {checked} rows");
    assert!(
        mismatches.is_empty(),
        "{} disagreements with GEOS:\n{}",
        mismatches.len(),
        mismatches.iter().take(20).cloned().collect::<Vec<_>>().join("\n")
    );
}
